import type { TACFunction, CFG, BasicBlock, Instruction, NaturalLoop } from './types.ts';

export const equalSets = <T>(a: Set<T>, b: Set<T>): boolean => a.size === b.size && Array.from(a).every(value => b.has(value));
export function intersection<T>(sets: Set<T>[]): Set<T> {
  if (sets.length === 0) return new Set<T>();
  return new Set<T>(Array.from(sets[0]).filter(value => sets.slice(1).every(set => set.has(value))));
}
export const numeric = (values: Iterable<number>): number[] => Array.from(values).sort((a, b) => a - b);

export function buildCFG(fn: TACFunction): CFG {
  const blocks: BasicBlock[] = [];
  const instructions = new Map<number, Instruction>();
  const owner = new Map<number, number>();
  const labels = new Map<string, number>();
  let pending: string[] = [], start = 0;
  let previous: Instruction | null = null, block: BasicBlock | null = null, number = 0;
  for (let i = 0; i < fn.code.length; i++) {
    const instruction = fn.code[i];
    if (instruction.kind === 'label') {
      if (pending.length === 0) start = i;
      pending.push(instruction.name!); continue;
    }
    instruction.number = ++number; instructions.set(number, instruction);
    if (block === null || pending.length || ['goto', 'if', 'return'].includes(previous!.kind)) {
      block = { number: blocks.length + 1, labels: pending, instructions: [], start: pending.length ? start : i,
        successors: [], predecessors: [], depth: 0 };
      blocks.push(block);
      for (const name of pending) labels.set(name, block.number);
      pending = [];
    }
    block.instructions.push(instruction); owner.set(number, block.number); previous = instruction;
  }
  const byNumber = new Map<number, BasicBlock>(blocks.map(b => [b.number, b]));
  for (const current of blocks) {
    const last = current.instructions[current.instructions.length - 1], next = current.number + 1;
    if (last.kind === 'goto') current.successors = [labels.get(last.target!)!];
    else if (last.kind === 'if') current.successors = Array.from(new Set([next, labels.get(last.target!)!]));
    else if (last.kind !== 'return') current.successors = [next];
    for (const target of current.successors) byNumber.get(target)!.predecessors.push(current.number);
  }
  const reachable = new Set<number>([1]), postorder: number[] = [], stack = [{ number: 1, next: 0 }];
  while (stack.length) {
    const frame = stack[stack.length - 1], successors = byNumber.get(frame.number)!.successors;
    if (frame.next === successors.length) { postorder.push(frame.number); stack.pop(); }
    else {
      const target = successors[frame.next++];
      if (!reachable.has(target)) { reachable.add(target); stack.push({ number: target, next: 0 }); }
    }
  }
  const reversePostorder = postorder.slice().reverse(), dominators = new Map<number, Set<number>>();
  const reachablePredecessors = (n: number): number[] => byNumber.get(n)!.predecessors.filter(p => reachable.has(p));
  for (const n of reachable) dominators.set(n, n === 1 ? new Set([1]) : new Set(reachable));
  let changed;
  do {
    changed = false;
    for (const n of reversePostorder.slice(1)) {
      const next = intersection(reachablePredecessors(n).map(p => dominators.get(p)!)); next.add(n);
      if (!equalSets(next, dominators.get(n)!)) { dominators.set(n, next); changed = true; }
    }
  } while (changed);
  const immediate = new Map<number, number | null>([[1, null]]);
  for (const n of reachable) if (n !== 1) {
    const ancestors = Array.from(dominators.get(n)).filter(p => p !== n);
    ancestors.sort((a, b) => dominators.get(b).size - dominators.get(a).size || a - b);
    immediate.set(n, ancestors[0]);
  }
  const loops: NaturalLoop[] = [];
  for (const header of blocks) if (reachable.has(header.number)) {
    const h = header.number, latches = reachablePredecessors(h).filter(t => dominators.get(t)!.has(h));
    if (latches.length === 0) continue;
    const members = new Set<number>([h, ...latches]), work = latches.filter(t => t !== h);
    while (work.length) {
      const current = work.pop()!;
      for (const p of reachablePredecessors(current)) if (!members.has(p)) { members.add(p); if (p !== h) work.push(p); }
    }
    const exits = new Set<number>(), outside = new Set<number>();
    for (const n of members) {
      const member = byNumber.get(n)!;
      if (member.instructions[member.instructions.length - 1].kind === 'return') exits.add(n);
      for (const successor of member.successors) if (!members.has(successor)) { exits.add(n); outside.add(successor); }
    }
    loops.push({ header: h, latches, blocks: members, exits, outside, depth: 0 });
  }
  for (const loop of loops) loop.depth = loops.filter(other => other.blocks.has(loop.header)).length;
  for (const current of blocks) current.depth = loops.filter(loop => loop.blocks.has(current.number)).length;
  return { blocks, byNumber, instructions, owner, labels, reachable, postorder, reversePostorder,
    dominators, immediate, loops, reachablePredecessors };
}

import { definition, uses, variable, expression, expressionKey } from './tac_parser.ts';
import { buildCFG, equalSets, intersection } from './cfg.ts';
import type { TACFunction, Instruction, Analysis, Flow, Definition, Expression } from './types.ts';
const definitionKey = (name: string, number: number): string => number + ':' + name;
const copyKey = (left: string, right: string): string => left + ',' + right;
const union = (sets: Set<string>[]): Set<string> => new Set<string>(sets.flatMap(set => Array.from(set)));

export function liveTransfer(instruction: Instruction, state: Set<string>): Set<string> {
  const next = new Set(state); next.delete(definition(instruction)!);
  for (const name of uses(instruction)) next.add(name);
  return next;
}

export function analyze(fn: TACFunction): Analysis {
  const graph = buildCFG(fn);
  const definitions = new Map<string, Definition>();
  const expressions = new Map<string, Expression>();
  const copyPairs = new Map<string, [string, string]>();
  const parameters = new Set<string>(fn.parameters.map(name => definitionKey(name, 0)));
  for (const name of fn.parameters) definitions.set(definitionKey(name, 0), { name, number: 0 });
  for (const block of graph.blocks) if (graph.reachable.has(block.number)) {
    for (const instruction of block.instructions) {
      const name = definition(instruction);
      if (name !== undefined) definitions.set(definitionKey(name, instruction.number!), { name, number: instruction.number! });
      const value = expression(instruction);
      if (value !== null) expressions.set(expressionKey(instruction)!, value);
      if (instruction.kind === 'copy' && variable(instruction.a) && instruction.a !== instruction.dest) {
        copyPairs.set(copyKey(instruction.dest!, instruction.a), [instruction.dest!, instruction.a]);
      }
    }
  }
  const transfers: Record<string,(instruction: Instruction, state: Set<string>)=>Set<string>> = {
    rd(instruction: Instruction, state: Set<string>): Set<string> {
      const next = new Set(state), name = definition(instruction);
      if (name !== undefined) {
        for (const key of next) if (definitions.get(key)!.name === name) next.delete(key);
        next.add(definitionKey(name, instruction.number!));
      }
      return next;
    },
    available(instruction: Instruction, state: Set<string>): Set<string> {
      const next = new Set(state), key = expressionKey(instruction), name = definition(instruction);
      if (key !== null) next.add(key);
      for (const candidate of next) {
        const value = expressions.get(candidate)!;
        if ((instruction.kind === 'store' && value.kind === 'load' && value.array === instruction.array)
            || (instruction.kind === 'call' && value.kind === 'load')
            || (name !== undefined && (value.a === name || value.b === name))) next.delete(candidate);
      }
      return next;
    },
    copies(instruction: Instruction, state: Set<string>): Set<string> {
      const next = new Set(state), name = definition(instruction);
      if (name !== undefined) for (const key of next) if (copyPairs.get(key)!.includes(name)) next.delete(key);
      if (instruction.kind === 'copy' && variable(instruction.a) && instruction.dest !== instruction.a) next.add(copyKey(instruction.dest!, instruction.a));
      return next;
    }
  };
  const flows: Record<string,Flow> = {};
  for (const kind of ['rd', 'live', 'available', 'copies']) {
    const live = kind === 'live', universe = kind === 'available' ? new Set(expressions.keys()) :
      kind === 'copies' ? new Set(copyPairs.keys()) : new Set();
    const incoming = new Map<number, Set<string>>(), outgoing = new Map<number, Set<string>>();
    for (const n of graph.reachable) { incoming.set(n, new Set()); outgoing.set(n, new Set<string>(universe)); }
    let changed, iterations = 0;
    do {
      changed = false; iterations++;
      for (const n of live ? graph.postorder : graph.reversePostorder) {
        const block = graph.byNumber.get(n)!;
        if (live) {
          const out = union(block.successors.map(s => incoming.get(s)!));
          let state = out;
          for (let i = block.instructions.length - 1; i >= 0; i--) state = liveTransfer(block.instructions[i], state);
          if (!equalSets(state, incoming.get(n)!)) changed = true;
          outgoing.set(n, out); incoming.set(n, state);
        } else {
          const predecessorSets = graph.reachablePredecessors(n).map(p => outgoing.get(p)!);
          const entry: Set<string> = kind === 'rd' ? union(n === 1 ? [parameters, ...predecessorSets] : predecessorSets) :
            n === 1 ? new Set<string>() : intersection(predecessorSets);
          let state = entry;
          for (const instruction of block.instructions) state = transfers[kind](instruction, state);
          if (!equalSets(state, outgoing.get(n)!)) changed = true;
          incoming.set(n, entry); outgoing.set(n, state);
        }
      }
    } while (changed);
    const before = new Map<number, Set<string>>(), after = new Map<number, Set<string>>();
    for (const block of graph.blocks) if (graph.reachable.has(block.number)) {
      if (live) {
        let state = outgoing.get(block.number);
        for (let i = block.instructions.length - 1; i >= 0; i--) {
          const instruction = block.instructions[i]; after.set(instruction.number, state);
          state = liveTransfer(instruction, state); before.set(instruction.number, state);
        }
      } else {
        let state = incoming.get(block.number);
        for (const instruction of block.instructions) {
          before.set(instruction.number, state); state = transfers[kind](instruction, state); after.set(instruction.number, state);
        }
      }
    }
    flows[kind] = { incoming, outgoing, before, after, iterations };
  }
  return { ...graph, rd: flows.rd, live: flows.live, available: flows.available,
    copies: flows.copies, definitions, expressions, copyPairs };
}

export function reaching(analysis: Analysis, instruction: Instruction, name: string): Definition[] {
  return Array.from(analysis.rd.before.get(instruction.number!)!).map(key => analysis.definitions.get(key)!).filter(value => value.name === name);
}

import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { KINDS, variable, copy, readProgram, definition, operandSlots, uses, expressionKey, expressionText,
  operation, instructionText, functionLines, programLines, cloneProgram } from './tac_parser.ts';
import { analyze, reaching, liveTransfer } from './dataflow.ts';
import { numeric } from './cfg.ts';
import { fold, rewrite, eliminateExpressions, hoist, removeUnreachable } from './optimizations.ts';
import { allocate, ascii } from './regalloc.ts';
import type { Operand, Instruction, TACFunction, TACProgram, Analysis,
  OptimizationRecord, CommonExpressionGroup, Settings, CallGraph,
  FunctionRuntime, Frame, ExecutionResult } from './types.ts';

const PASS_ORDER = ['constprop', 'copyprop', 'cse', 'dce', 'licm', 'unreachable'];
const list = (values: (string|number)[]): string => values.length ? values.join(',') : '-';
const blockList = (values: Iterable<number>): string => list(Array.from(values, number => 'B' + number));
const instructionList = (values: number[]): string => list(values.map(number => '#' + number));
const instructionCount = (fn: TACFunction): number => fn.code.filter(s => s.kind !== 'label').length;
const reachableInstructions = (analysis: Analysis): Instruction[] => analysis.blocks.filter(b => analysis.reachable.has(b.number)).flatMap(b => b.instructions);

function constantPropagation(fn: TACFunction, analysis: Analysis): OptimizationRecord {
  const replacements = new Map<number, Instruction[]>(), records: string[] = [];
  for (const source of reachableInstructions(analysis)) {
    const instruction = copy(source);
    for (const slot of operandSlots(source)) if (variable(source[slot])) {
      const name = source[slot] as string, definitions = reaching(analysis, source, source[slot] as string);
      if (definitions.length === 0 || definitions.some(value => value.number === 0)) continue;
      const assignments = definitions.map(value => analysis.instructions.get(value.number)!);
      if (assignments.some(s => s.kind !== 'copy' || variable(s.a))) continue;
      const value = assignments[0].a;
      if (!assignments.every(s => s.a === value)) continue;
      instruction[slot] = value;
      records.push('#' + source.number + ': ' + name + ' -> ' + value);
    }
    const result = fold(instruction);
    if (result.changed) {
      const description = result.instruction === null ? 'delete ' + instructionText(instruction) : 'fold ' + instructionText(result.instruction);
      records.push('#' + source.number + ': ' + description);
    }
    replacements.set(source.number!, result.instruction === null ? [] : [result.instruction]);
  }
  rewrite(fn, replacements);
  return { count: records.length, records };
}

function copyPropagation(fn: TACFunction, analysis: Analysis): OptimizationRecord {
  const replacements = new Map<number, Instruction[]>(), records: string[] = [];
  for (const source of reachableInstructions(analysis)) {
    const instruction = copy(source);
    const pairs = new Map<string,string>(Array.from(analysis.copies.before.get(source.number!)!, key => analysis.copyPairs.get(key)!));
    for (const slot of operandSlots(source)) if (variable(source[slot]) && pairs.has(source[slot] as string)) {
      const name = source[slot] as string, target = pairs.get(name)!; instruction[slot] = target;
      records.push('#' + source.number + ': ' + name + ' -> ' + target);
    }
    replacements.set(source.number, [instruction]);
  }
  rewrite(fn, replacements);
  return { count: records.length, records };
}

function commonSubexpressions(fn: TACFunction, analysis: Analysis): OptimizationRecord {
  const groups = new Map<string, {key: string; candidates: Instruction[]; sources: Set<number>}>();
  for (const instruction of reachableInstructions(analysis)) {
    const key = expressionKey(instruction);
    if (key !== null && analysis.available.before.get(instruction.number!)!.has(key)) {
      if (!groups.has(key)) groups.set(key, { key, candidates: [], sources: new Set<number>() });
      groups.get(key)!.candidates.push(instruction);
    }
  }
  for (const group of groups.values()) {
    for (const candidate of group.candidates) {
      const block = analysis.byNumber.get(analysis.owner.get(candidate.number!)!)!;
      const earlier = block.instructions.filter(s => s.number! < candidate.number! && expressionKey(s) === group.key);
      if (earlier.length) { group.sources.add(earlier[earlier.length - 1].number!); continue; }
      const work = analysis.reachablePredecessors(block.number).slice(), examined = new Set<number>();
      while (work.length) {
        const number = work.pop()!;
        if (examined.has(number)) continue;
        examined.add(number);
        const instructions = analysis.byNumber.get(number)!.instructions;
        let found = null;
        for (let i = instructions.length - 1; i >= 0; i--) if (expressionKey(instructions[i]) === group.key) { found = instructions[i]; break; }
        if (found !== null) group.sources.add(found.number!);
        else work.push(...analysis.reachablePredecessors(number));
      }
    }
    const candidates = new Set<number>(group.candidates.map(s => s.number!));
    group.sources = new Set<number>(numeric(group.sources).filter(n => !candidates.has(n)));
  }
  const prepared: CommonExpressionGroup[] = Array.from(groups.values()).map(group => ({
    key: group.key, candidates: group.candidates,
    sources: numeric(group.sources).map(n => analysis.instructions.get(n)!)
  }));
  const results = eliminateExpressions(fn, prepared);
  const records = results.map(group => expressionText(analysis.expressions.get(group.key)!) + ': ' + group.temporary +
    ' sources=' + instructionList(group.sources.map(s => s.number!)) + ' replaced=' + instructionList(group.candidates.map(s => s.number!)));
  return { count: results.reduce((sum, group) => sum + group.candidates.length, 0), records };
}

function deadCode(fn: TACFunction, analysis: Analysis): OptimizationRecord {
  const replacements = new Map<number, Instruction[]>(), records: {number:number;text:string}[] = [];
  for (const block of analysis.blocks) if (analysis.reachable.has(block.number)) {
    let live = new Set<string>(analysis.live.outgoing.get(block.number)!);
    for (let i = block.instructions.length - 1; i >= 0; i--) {
      let instruction = block.instructions[i];
      const number = instruction.number!, defined = definition(instruction), text = instructionText(instruction);
      if ((instruction.kind === 'copy' && instruction.dest === instruction.a)
          || (['copy', 'bin', 'load'].includes(instruction.kind) && !live.has(defined!))) {
        replacements.set(number, []); records.push({ number, text: '#' + number + ': delete ' + text }); continue;
      }
      if (instruction.kind === 'call' && defined !== undefined && !live.has(defined)) {
        instruction = copy(instruction); delete instruction.dest; replacements.set(number, [instruction]);
        records.push({ number, text: '#' + number + ': unused result ' + text });
      }
      live = liveTransfer(instruction, live);
    }
  }
  rewrite(fn, replacements); records.sort((a, b) => a.number - b.number);
  return { count: records.length, records: records.map(record => record.text) };
}

function invariantMotion(fn: TACFunction, analysis: Analysis): OptimizationRecord {
  const loops = analysis.loops.slice().sort((a, b) => a.blocks.size - b.blocks.size || a.header - b.header);
  for (const loop of loops) {
    const instructions = reachableInstructions(analysis).filter(s => loop.blocks.has(analysis.owner.get(s.number!)!));
    const marked = new Set<number>(), markOrder: Instruction[] = [], definitionCounts = new Map<string,number>();
    const stores = new Set<string>(instructions.filter(s => s.kind === 'store').map(s => s.array!));
    const hasCall = instructions.some(s => s.kind === 'call');
    for (const instruction of instructions) {
      const name = definition(instruction);
      if (name !== undefined) definitionCounts.set(name, (definitionCounts.get(name!) || 0) + 1);
    }
    const inside = (value: {number:number}): boolean => value.number !== 0 && loop.blocks.has(analysis.owner.get(value.number)!);
    let changed;
    do {
      changed = false;
      for (const instruction of instructions) {
        if (marked.has(instruction.number!) || !['copy', 'bin', 'load'].includes(instruction.kind)) continue;
        if (instruction.kind === 'load' && (hasCall || stores.has(instruction.array!))) continue;
        const invariant = uses(instruction).every(name => {
          const definitions = reaching(analysis, instruction, name);
          return definitions.every(value => !inside(value)) ||
            (definitions.length === 1 && inside(definitions[0]) && marked.has(definitions[0].number));
        });
        if (invariant) { marked.add(instruction.number!); markOrder.push(instruction); changed = true; }
      }
    } while (changed);
    const moving: Instruction[] = [], moved = new Set<number>();
    for (const instruction of markOrder) {
      const name = definition(instruction), block = analysis.owner.get(instruction.number!)!;
      if (definitionCounts.get(name) !== 1 || analysis.live.incoming.get(loop.header)!.has(name!)) continue;
      const dominatesExits = Array.from(loop.exits).every(exit => analysis.dominators.get(exit)!.has(block));
      const dangerous = instruction.kind === 'load' ||
        (instruction.kind === 'bin' && ['/', '%'].includes(instruction.op) && (variable(instruction.b) || instruction.b === 0));
      const deadOutside = Array.from(loop.outside).every(successor => !analysis.live.incoming.get(successor)!.has(name!));
      if (!dominatesExits && (dangerous || !deadOutside)) continue;
      if (!uses(instruction).every(operand => reaching(analysis, instruction, operand).filter(inside).every(value => moved.has(value.number)))) continue;
      moving.push(instruction); moved.add(instruction.number!);
    }
    if (moving.length) {
      const numbers = moving.map(s => s.number!), destination = hoist(fn, analysis, loop, moving);
      return { count: moving.length, records: ['B' + loop.header + ': hoist ' + instructionList(numbers) + ' to ' + destination] };
    }
  }
  return { count: 0, records: [] };
}

function unreachableCode(fn: TACFunction, analysis: Analysis): OptimizationRecord {
  const removed = removeUnreachable(fn, analysis);
  const records = [...removed.blocks.map(n => 'remove block B' + n), ...removed.jumps.map(n => 'remove jump #' + n),
    ...removed.labels.map(name => 'remove label ' + name)];
  return { count: records.length, records };
}

function callGraph(program: TACProgram): CallGraph {
  const names = program.functions.map(fn => fn.name), edges = new Map<string,string[]>();
  for (const fn of program.functions) {
    const callees = new Set<string>(fn.code.filter(s => s.kind === 'call').map(s => s.name!));
    edges.set(fn.name, names.filter(name => callees.has(name)));
  }
  const follow = (starts: string[]): Set<string> => {
    const marked = new Set<string>(), work = starts.slice();
    while (work.length) {
      const name = work.pop();
      if (marked.has(name)) continue;
      marked.add(name); work.push(...edges.get(name)!);
    }
    return marked;
  };
  const reachable = follow(['main']);
  const recursive = new Set(names.filter(name => follow(edges.get(name)!).has(name)));
  const unreachable = names.filter(name => !reachable.has(name));
  return { edges, reachable, recursive, unreachable };
}

function graphLines(program: TACProgram, graph: CallGraph): string[] {
  return [...program.functions.map(fn => fn.name + ' -> ' + list(graph.edges.get(fn.name)!) + (graph.recursive.has(fn.name) ? ' (recursive)' : '')),
    'unreachable functions: ' + list(graph.unreachable)];
}

function optimize(program: TACProgram, settings: Settings): {records: string[]; callLines: string[]} {
  const passes = PASS_ORDER.filter(name => settings.passes.has(name));
  const handlers: Record<string,(fn:TACFunction,analysis:Analysis)=>OptimizationRecord> = { constprop: constantPropagation, copyprop: copyPropagation, cse: commonSubexpressions,
    dce: deadCode, licm: invariantMotion, unreachable: unreachableCode };
  const totals = new Map<string,number>(passes.map(name => [name, 0])), records: string[] = [];
  for (const fn of program.functions) {
    const before = instructionCount(fn); let rounds = 0;
    records.push('== ' + fn.name + ' ==');
    for (let round = 1; round <= settings.rounds; round++) {
      const counts: string[] = [], details: string[] = []; let changed = 0; rounds = round;
      for (const name of passes) {
        const result = handlers[name](fn, analyze(fn));
        counts.push(name + '=' + result.count); changed += result.count;
        totals.set(name, totals.get(name)! + result.count);
        details.push(...result.records.map(record => '  ' + name + ' ' + record));
      }
      records.push('round ' + round + ': ' + counts.join(' '), ...details);
      if (changed === 0) break;
    }
    records.push('result: rounds=' + rounds + ' instructions=' + before + '->' + instructionCount(fn));
  }
  const graph = callGraph(program), callLines = graphLines(program, graph);
  const removed = settings.passes.has('unreachable') ? graph.unreachable : [];
  const removedSet = new Set(removed); program.functions = program.functions.filter(fn => !removedSet.has(fn.name));
  records.push('== program ==', 'removed functions: ' + list(removed), '== total ==', passes.map(name => name + '=' + totals.get(name)).join(' '));
  return { records, callLines };
}

function analysisLines(fn: TACFunction, type: string, analysis: Analysis): string[] {
  const lines: string[] = ['== ' + fn.name + ' (' + type + ') ==', 'code:'];
  for (const instruction of fn.code) {
    if (instruction.kind === 'label') { lines.push(instructionText(instruction)); continue; }
    let line = '  #' + instruction.number + ' ' + instructionText(instruction);
    if (analysis.reachable.has(analysis.owner.get(instruction.number!)!)) {
      const names = Array.from(new Set(uses(instruction)));
      if (names.length) line += ' | ' + names.map(name => name + ':' +
        list(reaching(analysis, instruction, name).map(value => value.number).sort((a, b) => a - b))).join(' ');
    }
    lines.push(line);
  }
  lines.push('blocks: ' + analysis.blocks.length);
  for (const block of analysis.blocks) {
    lines.push('B' + block.number + ' ' + block.instructions[0].number + '-' + block.instructions[block.instructions.length - 1].number +
      ' labels=' + list(block.labels) + ' preds=' + blockList(block.predecessors) + ' succs=' + blockList(block.successors));
  }
  lines.push('unreachable: ' + blockList(analysis.blocks.filter(b => !analysis.reachable.has(b.number)).map(b => b.number)),
    'order: ' + blockList(analysis.reversePostorder), 'dominators:');
  const reachable = analysis.blocks.filter(b => analysis.reachable.has(b.number));
  for (const block of reachable) {
    const parent = analysis.immediate.get(block.number);
    lines.push('B' + block.number + ' idom=' + (parent === null ? '-' : 'B' + parent) +
      ' dom=' + blockList(numeric(analysis.dominators.get(block.number)!)));
  }
  lines.push('dominator tree:');
  const stack = [{ number: 1, depth: 0 }];
  while (stack.length) {
    const current = stack.pop(); lines.push(' '.repeat(2 * current.depth) + 'B' + current.number);
    const children = reachable.filter(b => analysis.immediate.get(b.number) === current.number);
    for (let i = children.length - 1; i >= 0; i--) stack.push({ number: children[i].number, depth: current.depth + 1 });
  }
  lines.push('loops: ' + analysis.loops.length);
  for (const loop of analysis.loops) {
    lines.push('header=B' + loop.header + ' latches=' + blockList(loop.latches) + ' depth=' + loop.depth +
      ' blocks=' + blockList(numeric(loop.blocks)) + ' exits=' + blockList(numeric(loop.exits)));
  }
  for (const [kind, title] of [['rd', 'reaching definitions'], ['live', 'liveness'], ['available', 'available expressions']]) {
    const flow = analysis[kind as 'rd'|'live'|'available'];
    const render = (set: Set<string>): string => {
      if (kind === 'rd') {
        const definitions = Array.from(set, key => analysis.definitions.get(key)!);
        definitions.sort((a, b) => a.number - b.number || ascii(a.name, b.name));
        return list(definitions.map(value => value.name + ':' + value.number));
      }
      const values = kind === 'available' ? Array.from(set, key => expressionText(analysis.expressions.get(key)!)) : Array.from(set);
      return list(values.sort(ascii));
    };
    lines.push(title + ': iterations=' + flow.iterations);
    for (const block of reachable) lines.push('B' + block.number + ' in=' + render(flow.incoming.get(block.number)) +
      ' out=' + render(flow.outgoing.get(block.number)));
  }
  return lines;
}

function allocateFunction(fn: TACFunction, analysis: Analysis, registers: number): {fn:TACFunction; lines:string[]} {
  const allocation = allocate(fn, analysis, registers), { colors, nodes } = allocation;
  const rename = (name: string): string => colors.has(name) && colors.get(name) !== null ? 'R' + colors.get(name) : name;
  let moves = 0, pressure = 0, spillUses = 0, spillDefs = 0;
  const spilled = new Set<string>(nodes.filter(name => colors.get(name) === null));
  for (const parameter of fn.parameters) if (spilled.has(parameter)) spillDefs++;
  const code: Instruction[] = [];
  for (const source of fn.code) {
    if (source.kind === 'label') { code.push(copy(source)); continue; }
    const instruction = copy(source), defined = definition(source);
    if (defined !== undefined) {
      if (spilled.has(defined)) spillDefs++;
      instruction.dest = rename(defined);
    }
    for (const slot of operandSlots(source)) if (variable(source[slot])) {
      if (spilled.has(source[slot] as string)) spillUses++;
      instruction[slot] = rename(source[slot] as string);
    }
    if (instruction.kind === 'copy' && instruction.dest === instruction.a) moves++;
    else code.push(instruction);
    if (analysis.live.before.has(source.number)) pressure = Math.max(pressure,
      analysis.live.before.get(source.number!)!.size, analysis.live.after.get(source.number!)!.size);
  }
  const result = { ...fn, parameters: fn.parameters.map(rename), code };
  const lines = ['== ' + fn.name + ' ==', 'nodes=' + nodes.length + ' edges=' + allocation.edges + ' registers=' + registers];
  for (const name of nodes) lines.push(name + ' degree=' + allocation.neighbors.get(name)!!.size + ' cost=' + allocation.costs.get(name)! +
    ' neighbors=' + list(Array.from(allocation.neighbors.get(name)).sort(ascii)));
  lines.push('simplify: ' + list(allocation.order),
    'potential spills: ' + list(allocation.potential.map(value => value.name + '(' + value.cost + '/' + value.degree + ')')));
  for (const name of nodes) lines.push(name + ' -> ' + (colors.get(name) === null ? 'spill' : 'R' + colors.get(name)));
  const used = new Set<number>(Array.from(colors.values()).filter((color): color is number => color !== null)).size;
  lines.push('summary: pressure=' + pressure + ' used=' + used + ' spilled=' + spilled.size + ' moves=' + moves +
    ' spill_uses=' + spillUses + ' spill_defs=' + spillDefs, ...functionLines(result));
  return { fn: result, lines };
}

function execute(program: TACProgram, input: number[]): ExecutionResult {
  const functions = new Map<string, FunctionRuntime>();
  const calls = new Map<string,number>(), steps = new Map<string,number>();
  const kinds: Record<string,number> = Object.fromEntries(KINDS.map(kind => [kind, 0]));
  for (const fn of program.functions) {
    const instructions: Instruction[] = [], labels = new Map<string,number>();
    for (const instruction of fn.code) {
      if (instruction.kind === 'label') labels.set(instruction.name!, instructions.length);
      else instructions.push(instruction);
    }
    functions.set(fn.name, { ...fn, instructions, labels }); calls.set(fn.name, 0); steps.set(fn.name, 0);
  }
  const arrays = new Map<string,number[]>(program.arrays.map(array => [array.name, Array<number>(array.size).fill(0)]));
  const stack: Frame[] = [], output: number[] = []; let inputIndex = 0;
  const push = (name: string, argumentsList: number[], destination: string | undefined): void => {
    const fn = functions.get(name)!, values = new Map<string,number>(fn.parameters.map((parameter, i) => [parameter, argumentsList[i]]));
    stack.push({ fn, values, pc: 0, arguments: [], destination });
    calls.set(name, calls.get(name)! + 1);
  };
  push('main', [], undefined);
  while (stack.length) {
    const frame = stack[stack.length - 1], instruction = frame.fn.instructions[frame.pc++];
    const value = (operand: Operand | undefined): number => variable(operand) ? frame.values.get(operand)! : operand as number;
    steps.set(frame.fn.name, steps.get(frame.fn.name)! + 1); kinds[instruction.kind]++;
    switch (instruction.kind) {
      case 'copy': frame.values.set(instruction.dest!, value(instruction.a)); break;
      case 'bin': frame.values.set(instruction.dest, operation(instruction.op!, value(instruction.a), value(instruction.b))); break;
      case 'load': frame.values.set(instruction.dest, arrays.get(instruction.array!)![value(instruction.a)]); break;
      case 'store': arrays.get(instruction.array)[value(instruction.a)] = value(instruction.b); break;
      case 'goto': frame.pc = frame.fn.labels.get(instruction.target!)!; break;
      case 'if': if (operation(instruction.op!, value(instruction.a), value(instruction.b))) frame.pc = frame.fn.labels.get(instruction.target); break;
      case 'param': frame.arguments.push(value(instruction.a)); break;
      case 'call': {
        const argumentsList = frame.arguments.splice(frame.arguments.length - instruction.count!, instruction.count!);
        push(instruction.name!, argumentsList, instruction.dest); break;
      }
      case 'return': {
        const result = instruction.a === undefined ? undefined : value(instruction.a);
        stack.pop();
        if (stack.length && frame.destination !== undefined) stack[stack.length - 1].values.set(frame.destination, result!);
        break;
      }
      case 'read': frame.values.set(instruction.dest, input[inputIndex++]); break;
      case 'print': output.push(value(instruction.a)); break;
    }
  }
  return { output, calls, steps, kinds, totalSteps: Array.from(steps.values()).reduce((a, b) => a + b, 0),
    totalCalls: Array.from(calls.values()).reduce((a, b) => a + b, 0) };
}

function staticKinds(program: TACProgram): Record<string,number> {
  const counts = Object.fromEntries(KINDS.map(kind => [kind, 0]));
  for (const fn of program.functions) for (const instruction of fn.code) if (instruction.kind !== 'label') counts[instruction.kind]++;
  return counts;
}

function comparePrograms(programs: TACProgram[], runs: number[][]): string[] {
  const names = ['original', 'optimized', 'allocated'], original = programs[0];
  const totals = programs.map(() => ({ 
    steps: new Map(original.functions.map(fn => [fn.name, 0])),
    calls: new Map(original.functions.map(fn => [fn.name, 0])),
    kinds: Object.fromEntries(KINDS.map(kind => [kind, 0])), totalSteps: 0
  }));
  const lines: string[] = []; let same = 0;
  for (let i = 0; i < runs.length; i++) {
    lines.push('run ' + (i + 1) + ': inputs=' + runs[i].length);
    const results = programs.map(program => execute(program, runs[i]));
    for (let j = 0; j < results.length; j++) {
      const result = results[j], total = totals[j];
      lines.push('  ' + names[j] + ': steps=' + result.totalSteps + ' calls=' + result.totalCalls + ' output=' + list(result.output));
      total.totalSteps += result.totalSteps;
      for (const [name, count] of result.calls) total.calls.set(name, total.calls.get(name)! + count);
      for (const [name, count] of result.steps) total.steps.set(name, total.steps.get(name)! + count);
      for (const kind of KINDS) total.kinds[kind] += result.kinds[kind];
    }
    const equal = results.slice(1).every(result => result.output.length === results[0].output.length &&
      result.output.every((value, index) => value === results[0].output[index]));
    if (equal) same++;
    lines.push('  result: ' + (equal ? 'same' : 'different'));
  }
  lines.push('== profile ==');
  for (const fn of original.functions) lines.push(fn.name + ': calls=' + totals[0].calls.get(fn.name) +
    ' original=' + totals[0].steps.get(fn.name) + ' optimized=' + totals[1].steps.get(fn.name) + ' allocated=' + totals[2].steps.get(fn.name));
  const counts = programs.slice(0, 2).map(staticKinds), instructions = programs.slice(0, 2).map(program =>
    program.functions.reduce((sum, fn) => sum + instructionCount(fn), 0));
  lines.push('== summary ==', 'runs=' + runs.length + ' same=' + same + ' different=' + (runs.length - same),
    'instructions: original=' + instructions[0] + ' optimized=' + instructions[1],
    'kinds: ' + KINDS.map(kind => kind + '=' + counts[0][kind] + '->' + counts[1][kind]).join(' '),
    'steps: ' + names.map((name, index) => name + '=' + totals[index].totalSteps).join(' '));
  for (let i = 0; i < names.length; i++) lines.push('dynamic ' + names[i] + ': ' + KINDS.map(kind => kind + '=' + totals[i].kinds[kind]).join(' '));
  return lines;
}

function main(): void {
  const parameters = readFileSync('input/params.txt', 'ascii').split('\n').map(line => line.split(' '));
  const settings = { registers: Number(parameters[0][1]), passes: new Set(parameters[1].slice(1)), rounds: Number(parameters[2][1]) };
  const input = fs.readFileSync('input/input.txt', 'ascii').trim().split('\n').map(line => line.split(/ +/).map(Number));
  const runs = input.slice(1, 1 + input[0][0]).map(line => line.slice(1, 1 + line[0]));
  const original = readProgram(), program = cloneProgram(original);
  const analyses = ['== call graph (original) ==', ...graphLines(original, callGraph(original))];
  for (const fn of original.functions) analyses.push(...analysisLines(fn, 'original', analyze(fn)));
  const passes = optimize(program, settings);
  analyses.push('== call graph (optimized) ==', ...passes.callLines);
  const allocated: TACProgram = { arrays: program.arrays.map(array => ({ ...array })), functions: [] };
  const allocationLines: string[] = [];
  for (const fn of program.functions) {
    const analysis = analyze(fn);
    analyses.push(...analysisLines(fn, 'optimized', analysis));
    const result = allocateFunction(fn, analysis, settings.registers);
    allocated.functions.push(result.fn); allocationLines.push(...result.lines);
  }
  const outputs = { 'optimized.tac': programLines(program), 'analysis.txt': analyses, 'passes.txt': passes.records,
    'regalloc.txt': allocationLines, 'comparison.txt': comparePrograms([original, program, allocated], runs) };
  mkdirSync('output', { recursive: true });
  for (const [name, lines] of Object.entries(outputs)) writeFileSync('output/' + name, lines.join('\n') + '\n', 'ascii');
}

main();

import { variable, operation } from './tac_parser.ts';
import type { TACFunction, Instruction, Analysis, NaturalLoop, CommonExpressionGroup, ExtractedGroup, RemovedCode } from './types.ts';

export function fold(instruction: Instruction): {changed: boolean; instruction: Instruction | null} {
  const s = instruction;
  if (s.kind === 'if' && !variable(s.a) && !variable(s.b)) {
    return { changed: true, instruction: operation(s.op!, s.a as number, s.b as number) ? { kind: 'goto', target: s.target, number: s.number } : null };
  }
  if (s.kind !== 'bin') return { changed: false, instruction: s };
  let value: number | string;
  if (!variable(s.a) && !variable(s.b)) {
    if ((s.op === '/' || s.op === '%') && s.b === 0) return { changed: false, instruction: s };
    value = operation(s.op!, s.a as number, s.b as number);
    if (value < -2147483648 || value > 2147483647) return { changed: false, instruction: s };
  } else if (variable(s.a) !== variable(s.b)) {
    const constant = variable(s.a) ? s.b : s.a, name = variable(s.a) ? s.a : s.b;
    if ((s.op === '+' && constant === 0) || (s.op === '-' && s.b === 0)
        || (s.op === '*' && constant === 1) || (s.op === '/' && s.b === 1)) value = name!;
    else if (s.op === '*' && constant === 0) value = 0;
    else return { changed: false, instruction: s };
  } else return { changed: false, instruction: s };
  return { changed: true, instruction: { kind: 'copy', dest: s.dest, a: value, number: s.number } };
}

export function rewrite(fn: TACFunction, replacements: Map<number, Instruction[]>): void {
  fn.code = fn.code.flatMap(instruction => instruction.kind === 'label' || !replacements.has(instruction.number!) ?
    [instruction] : replacements.get(instruction.number!)!);
}

export function eliminateExpressions(fn: TACFunction, groups: CommonExpressionGroup[]): ExtractedGroup[] {
  const replacements = new Map<number, Instruction[]>(), results: ExtractedGroup[] = [];
  for (const group of groups) {
    const temporary = '_t' + (++fn.temporary);
    for (const source of group.sources) replacements.set(source.number!, [
      { ...source, dest: temporary }, { kind: 'copy', dest: source.dest, a: temporary }
    ]);
    for (const candidate of group.candidates) replacements.set(candidate.number!, [
      { kind: 'copy', dest: candidate.dest, a: temporary, number: candidate.number }
    ]);
    results.push({ ...group, temporary });
  }
  rewrite(fn, replacements);
  return results;
}

export function hoist(fn: TACFunction, analysis: Analysis, loop: NaturalLoop, moving: Instruction[]): string {
  const header = analysis.byNumber.get(loop.header)!;
  const outside = header.predecessors.filter(n => !loop.blocks.has(n));
  const moved = new Set(moving.map(s => s.number!)), replacements = new Map<number, Instruction>();
  let index: number, inserted: Instruction[], destination: string;
  if (loop.header !== 1 && outside.length === 1 && analysis.byNumber.get(outside[0])!.successors.length === 1) {
    const preheader = analysis.byNumber.get(outside[0])!, last = preheader.instructions[preheader.instructions.length - 1];
    index = fn.code.indexOf(last) + Number(!['goto', 'if'].includes(last.kind));
    inserted = moving; destination = 'B' + preheader.number;
  } else {
    const label = '_p' + (++fn.preheader); index = header.start;
    inserted = [{ kind: 'label', name: label }, ...moving]; destination = 'new ' + label;
    for (const n of outside) {
      const block = analysis.byNumber.get(n)!, last = block.instructions[block.instructions.length - 1];
      if (['goto', 'if'].includes(last.kind) && header.labels.includes(last.target)) replacements.set(last.number!, { ...last, target: label });
    }
  }
  const code: Instruction[] = [];
  for (let i = 0; i <= fn.code.length; i++) {
    if (i === index) code.push(...inserted);
    if (i === fn.code.length) break;
    const instruction = fn.code[i];
    if (instruction.kind === 'label') code.push(instruction);
    else if (!moved.has(instruction.number!)) code.push(replacements.get(instruction.number!) || instruction);
  }
  fn.code = code;
  return destination;
}

export function removeUnreachable(fn: TACFunction, analysis: Analysis): RemovedCode {
  const removedBlocks = analysis.blocks.filter(b => !analysis.reachable.has(b.number));
  const removedInstructions = new Set<number>(removedBlocks.flatMap(b => b.instructions.map(s => s.number!)));
  const removedBlockLabels = new Set<string>(removedBlocks.flatMap(b => b.labels));
  const first = fn.code.filter(s => s.kind === 'label' ? !removedBlockLabels.has(s.name) : !removedInstructions.has(s.number));
  const jumps: number[] = [];
  for (let i = 0; i < first.length; i++) if (['goto', 'if'].includes(first[i].kind)) {
    for (let j = i + 1; j < first.length && first[j].kind === 'label'; j++) if (first[j].name === first[i].target) {
      jumps.push(first[i].number!); break;
    }
  }
  const removedJumps = new Set(jumps), second = first.filter(s => s.kind === 'label' || !removedJumps.has(s.number));
  const targets = new Set<string>(second.filter(s => ['goto', 'if'].includes(s.kind)).map(s => s.target!));
  const labels = second.filter(s => s.kind === 'label' && !targets.has(s.name!)).map(s => s.name!);
  fn.code = second.filter(s => s.kind !== 'label' || targets.has(s.name));
  return { blocks: removedBlocks.map(b => b.number), jumps, labels };
}

import { definition, uses, variable } from './tac_parser.ts';
import { liveTransfer } from './dataflow.ts';
import type { TACFunction, Analysis, RegisterAllocation } from './types.ts';
export const ascii = (a: string, b: string): number => a < b ? -1 : a > b ? 1 : 0;

export function allocate(fn: TACFunction, analysis: Analysis, registers: number): RegisterAllocation {
  const nodeSet = new Set<string>(fn.parameters);
  for (const block of analysis.blocks) if (analysis.reachable.has(block.number)) {
    for (const instruction of block.instructions) {
      if (definition(instruction) !== undefined) nodeSet.add(definition(instruction)!);
      for (const name of uses(instruction)) nodeSet.add(name);
    }
  }
  const nodes = Array.from(nodeSet).sort(ascii);
  const neighbors = new Map<string,Set<string>>(nodes.map(name => [name, new Set<string>()]));
  const partners = new Map<string,Set<string>>(nodes.map(name => [name, new Set<string>()]));
  const costs = new Map<string,bigint>(nodes.map(name => [name, 0n]));
  const edge = (a: string, b: string): void => {
    if (a !== b) { neighbors.get(a)!.add(b); neighbors.get(b)!.add(a); }
  };
  for (const block of analysis.blocks) if (analysis.reachable.has(block.number)) {
    let live = analysis.live.outgoing.get(block.number)!;
    const weight = 10n ** BigInt(block.depth);
    for (let i = block.instructions.length - 1; i >= 0; i--) {
      const instruction = block.instructions[i], defined = definition(instruction);
      if (defined !== undefined) {
        for (const name of live) if (!(instruction.kind === 'copy' && variable(instruction.a) && name === instruction.a)) edge(defined, name);
        costs.set(defined, costs.get(defined)! + weight);
      }
      for (const name of uses(instruction)) costs.set(name, costs.get(name)! + weight);
      live = liveTransfer(instruction, live);
    }
  }
  const entry = new Set<string>([...analysis.live.incoming.get(1)!, ...fn.parameters]);
  for (const parameter of fn.parameters) {
    for (const name of entry) edge(parameter, name);
    costs.set(parameter, costs.get(parameter)! + 1n);
  }
  for (const instruction of fn.code) if (instruction.kind === 'copy' && variable(instruction.a) && instruction.a !== instruction.dest) {
    if (partners.has(instruction.dest)) partners.get(instruction.dest)!.add(instruction.a);
    if (partners.has(instruction.a)) partners.get(instruction.a)!.add(instruction.dest!);
  }
  const remaining = new Set<string>(nodes), order: string[] = [], potential: RegisterAllocation['potential'] = [];
  while (remaining.size) {
    const degree = new Map<string,number>(Array.from(remaining, name => [name, Array.from(neighbors.get(name)!).filter(other => remaining.has(other)).length]));
    const small = Array.from(remaining).filter(name => degree.get(name)! < registers);
    let selected;
    if (small.length) {
      small.sort((a, b) => degree.get(a)! - degree.get(b)! || ascii(a, b)); selected = small[0];
    } else {
      const candidates = Array.from(remaining);
      candidates.sort((a, b) => {
        const left = costs.get(a)! * BigInt(degree.get(b)!), right = costs.get(b)! * BigInt(degree.get(a)!);
        return left < right ? -1 : left > right ? 1 : ascii(a, b);
      });
      selected = candidates[0]; potential.push({ name: selected, cost: costs.get(selected)!, degree: degree.get(selected)! });
    }
    order.push(selected); remaining.delete(selected);
  }
  const colors = new Map<string,number|null>();
  for (let i = order.length - 1; i >= 0; i--) {
    const name = order[i], occupied = new Set<number|null|undefined>(Array.from(neighbors.get(name)!, other => colors.get(other)));
    const free = Array.from({ length: registers }, (_, n) => n).filter(n => !occupied.has(n));
    if (free.length === 0) { colors.set(name, null); continue; }
    const preferred = Array.from(partners.get(name)!, other => colors.get(other)).filter((color): color is number => color !== null && color !== undefined && free.includes(color)).sort((a, b) => a - b);
    colors.set(name, preferred.length ? preferred[0] : free[0]);
  }
  return { nodes, neighbors, costs, partners, order, potential, colors,
    edges: nodes.reduce((sum, name) => sum + neighbors.get(name)!.size, 0) / 2 };
}

import { readFileSync } from 'node:fs';
import type { Operand, OperandSlot, Instruction, Expression, TACProgram, TACFunction } from './types.ts';
export const KINDS = ['copy', 'bin', 'load', 'store', 'goto', 'if', 'param', 'call', 'return', 'read', 'print'];
export const variable = (operand: Operand | undefined): operand is string => typeof operand === 'string';
const operand = (word: string): Operand => /^[-0-9]/.test(word) ? Number(word) : word;
export const copy = (instruction: Instruction): Instruction => ({...instruction});

function parseInstruction(words: string[]): Instruction {
  const [first, second] = words;
  if (first === 'goto') return { kind: 'goto', target: second };
  if (first === 'if') return { kind: 'if', a: operand(second), op: words[2], b: operand(words[3]), target: words[5] };
  if (first === 'param' || first === 'print') return {kind: first as 'param' | 'print', a: operand(second)};
  if (first === 'return') return second === undefined ? {kind: 'return'} : {kind: 'return', a: operand(second)};
  if (first === 'read') return { kind: 'read', dest: second };
  if (first === 'call') return { kind: 'call', name: second, count: Number(words[2]) };
  if (first.includes('[')) {
    const bracket = first.indexOf('[');
    return { kind: 'store', array: first.slice(0, bracket), a: operand(first.slice(bracket + 1, -1)), b: operand(words[2]) };
  }
  const dest = first, source = words[2];
  if (source === 'call') return { kind: 'call', dest, name: words[3], count: Number(words[4]) };
  if (words.length === 5) return { kind: 'bin', dest, a: operand(source), op: words[3], b: operand(words[4]) };
  if (source.includes('[')) {
    const bracket = source.indexOf('[');
    return { kind: 'load', dest, array: source.slice(0, bracket), a: operand(source.slice(bracket + 1, -1)) };
  }
  return { kind: 'copy', dest, a: operand(source) };
}

export function readProgram(): TACProgram {
  const program: TACProgram = {arrays: [], functions: []};
  let current: TACFunction | null = null;
  for (const line of readFileSync('input/program.tac', 'ascii').split('\n')) {
    const words = line.trim().split(/ +/);
    if (words[0] === '' || words[0].startsWith('#')) continue;
    if (words[0] === 'array') program.arrays.push({ name: words[1], size: Number(words[2]) });
    else if (words[0] === 'func') {
      current = { name: words[1], parameters: words.slice(2), code: [], temporary: 0, preheader: 0 };
      program.functions.push(current);
    } else if (words[0] === 'end') current = null;
    else current!.code.push(words.length === 1 && words[0].endsWith(':') ?
      { kind: 'label', name: words[0].slice(0, -1) } : parseInstruction(words));
  }
  return program;
}

export function definition(instruction: Instruction): string | undefined { return instruction.dest; }
export function operandSlots(instruction: Instruction): OperandSlot[] {
  if (['bin', 'if', 'store'].includes(instruction.kind)) return ['a', 'b'];
  if (['copy', 'load', 'param', 'print', 'return'].includes(instruction.kind) && instruction.a !== undefined) return ['a'];
  return [];
}
export function uses(instruction: Instruction): string[] { return operandSlots(instruction).map(slot => instruction[slot]).filter(variable); }
export function expression(instruction: Instruction): Expression | null {
  if (instruction.kind === 'bin') return {kind: 'bin', op: instruction.op!, a: instruction.a!, b: instruction.b!};
  if (instruction.kind === 'load') return {kind: 'load', array: instruction.array!, a: instruction.a!};
  return null;
}
export function expressionKey(instruction: Instruction): string | null {
  const value = expression(instruction);
  return value === null ? null : JSON.stringify(value);
}
export function expressionText(value: Expression): string { return value.kind === 'load' ? value.array + '[' + value.a + ']' : '' + value.a + value.op + value.b; }

export function operation(operator: string, a: number, b: number): number {
  switch (operator) {
    case '+': return a + b;
    case '-': return a - b;
    case '*': return a * b;
    case '/': return Math.trunc(a / b);
    case '%': return a % b;
    case '<': return Number(a < b);
    case '<=': return Number(a <= b);
    case '>': return Number(a > b);
    case '>=': return Number(a >= b);
    case '==': return Number(a === b);
    case '!=': return Number(a !== b);
  }
  throw new Error('unknown operation: ' + operator);
}

export function instructionText(instruction: Instruction): string {
  const s = instruction;
  switch (s.kind) {
    case 'label': return s.name + ':';
    case 'copy': return s.dest + ' = ' + s.a;
    case 'bin': return s.dest + ' = ' + s.a + ' ' + s.op + ' ' + s.b;
    case 'load': return s.dest + ' = ' + s.array + '[' + s.a + ']';
    case 'store': return s.array + '[' + s.a + '] = ' + s.b;
    case 'goto': return 'goto ' + s.target;
    case 'if': return 'if ' + s.a + ' ' + s.op + ' ' + s.b + ' goto ' + s.target;
    case 'param': case 'print': return s.kind + ' ' + s.a;
    case 'call': return (s.dest === undefined ? '' : s.dest + ' = ') + 'call ' + s.name + ' ' + s.count;
    case 'return': return s.a === undefined ? 'return' : 'return ' + s.a;
    case 'read': return 'read ' + s.dest;
  }
}

export function functionLines(fn: TACFunction): string[] {
  return ['func ' + [fn.name, ...fn.parameters].join(' '),
    ...fn.code.map(s => (s.kind === 'label' ? '' : '    ') + instructionText(s)), 'end'];
}
export function programLines(program: TACProgram): string[] {
  const sections: string[][] = [];
  if (program.arrays.length) sections.push(program.arrays.map(a => 'array ' + a.name + ' ' + a.size));
  sections.push(...program.functions.map(functionLines));
  return sections.flatMap((section, index) => index === 0 ? section : ['', ...section]);
}
export function cloneProgram(program: TACProgram): TACProgram {
  return { arrays: program.arrays.map(a => ({ ...a })), functions: program.functions.map(f =>
    ({ ...f, parameters: f.parameters.slice(), code: f.code.map(copy) })) };
}

export type Operand = number | string;
export type OperandSlot = 'a' | 'b';
export type InstructionKind =
  'label' | 'copy' | 'bin' | 'load' | 'store' | 'goto' | 'if' |
  'param' | 'call' | 'return' | 'read' | 'print';

export interface Instruction {
  kind: InstructionKind;
  number?: number;
  name?: string;
  dest?: string;
  a?: Operand;
  b?: Operand;
  op?: string;
  array?: string;
  target?: string;
  count?: number;
}
export interface Expression {
  kind: 'bin' | 'load';
  a: Operand;
  b?: Operand;
  op?: string;
  array?: string;
}
export interface TACFunction {
  name: string;
  parameters: string[];
  code: Instruction[];
  temporary: number;
  preheader: number;
}
export interface TACProgram {
  arrays: {name: string; size: number}[];
  functions: TACFunction[];
}
export interface BasicBlock {
  number: number;
  labels: string[];
  instructions: Instruction[];
  start: number;
  successors: number[];
  predecessors: number[];
  depth: number;
}
export interface NaturalLoop {
  header: number;
  latches: number[];
  blocks: Set<number>;
  exits: Set<number>;
  outside: Set<number>;
  depth: number;
}
export interface CFG {
  blocks: BasicBlock[];
  byNumber: Map<number, BasicBlock>;
  instructions: Map<number, Instruction>;
  owner: Map<number, number>;
  labels: Map<string, number>;
  reachable: Set<number>;
  postorder: number[];
  reversePostorder: number[];
  dominators: Map<number, Set<number>>;
  immediate: Map<number, number | null>;
  loops: NaturalLoop[];
  reachablePredecessors: (n: number) => number[];
}
export interface Flow {
  incoming: Map<number, Set<string>>;
  outgoing: Map<number, Set<string>>;
  before: Map<number, Set<string>>;
  after: Map<number, Set<string>>;
  iterations: number;
}
export interface Definition {name: string; number: number}
export interface Analysis extends CFG {
  rd: Flow;
  live: Flow;
  available: Flow;
  copies: Flow;
  definitions: Map<string, Definition>;
  expressions: Map<string, Expression>;
  copyPairs: Map<string, [string, string]>;
}
export interface CommonExpressionGroup {
  key: string;
  candidates: Instruction[];
  sources: Instruction[];
}
export interface ExtractedGroup extends CommonExpressionGroup {temporary: string}
export interface OptimizationRecord {count: number; records: string[]}
export interface RemovedCode {blocks: number[]; jumps: number[]; labels: string[]}
export interface RegisterAllocation {
  nodes: string[];
  neighbors: Map<string, Set<string>>;
  costs: Map<string, bigint>;
  partners: Map<string, Set<string>>;
  order: string[];
  potential: {name: string; cost: bigint; degree: number}[];
  colors: Map<string, number | null>;
  edges: number;
}
export interface Settings {registers: number; passes: Set<string>; rounds: number}
export interface CallGraph {
  edges: Map<string, string[]>;
  reachable: Set<string>;
  recursive: Set<string>;
  unreachable: string[];
}
export interface ExecutionResult {
  output: number[];
  calls: Map<string, number>;
  steps: Map<string, number>;
  kinds: Record<string, number>;
  totalSteps: number;
  totalCalls: number;
}
export interface FunctionRuntime extends TACFunction {
  instructions: Instruction[];
  labels: Map<string, number>;
}
